             clean_folder(os.path.join(folder, file_name))

+
+def _is_safe_archive_member(member_name, destination):
+    """Return True if the archive member would be extracted inside destination.
+
+    Protects against path traversal (Zip Slip) via absolute paths or '..'
+    components. destination must already exist.
+    """
+    # Reject absolute paths (Unix and Windows)
+    if os.path.isabs(member_name):
+        return False
+    # Normalize and resolve against the real destination directory
+    dest_real = os.path.realpath(destination)
+    target = os.path.realpath(os.path.join(destination, member_name))
+    try:
+        common = os.path.commonpath([dest_real, target])
+    except ValueError:
+        # Different drives on Windows, etc.
+        return False
+    return common == dest_real
+
+
 def extract_zip(zip_file, destination):
-    with zipfile.ZipFile(zip_file, "r") as zip_ref:
-        zip_ref.extractall(destination)
+    """Extract a zip archive to destination, rejecting path-traversal entries."""
+    os.makedirs(destination, exist_ok=True)
+    with zipfile.ZipFile(zip_file, "r") as zip_ref:
+        for info in zip_ref.infolist():
+            if not _is_safe_archive_member(info.filename, destination):
+                raise ValueError(
+                    f"Illegal path in zip archive (path traversal): {info.filename!r}"
+                )
+            zip_ref.extract(info, destination)
+
+
+def extract_tar(tar_file, destination):
+    """Extract a tar archive to destination, rejecting path-traversal entries."""
+    os.makedirs(destination, exist_ok=True)
+    with tarfile.open(tar_file, "r:*") as tar_ref:
+        for member in tar_ref.getmembers():
+            if not _is_safe_archive_member(member.name, destination):
+                raise ValueError(
+                    f"Illegal path in tar archive (path traversal): {member.name!r}"
+                )
+            tar_ref.extract(member, destination)
