diff --git a/lib/normalize-windows.js b/lib/normalize-windows.js
new file mode 100644
index 0000000..c3d4e5f
--- /dev/null
+++ b/lib/normalize-windows.js
@@ -0,0 +1,10 @@
+// Normalize Windows paths (from tar entries generated on Windows) to Unix-style
+// forward slashes so that path traversal checks cannot be bypassed with '\'.
+// See: https://github.com/mafintosh/tar-fs/security/advisories
+
+module.exports = function normalizeWindows (name) {
+  // remove the drive letter and turn any backslashes into forward slashes
+  // so that path operations treat the entry as a normal relative path
+  name = name.replace(/\\/g, '/')
+  return name
+}

